-- mistri store layout: inbox, sqlite, version 1. Generated by scripts/store-layouts.mjs; never edit by hand.
CREATE TABLE "__mistri_inbox_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 1)
);
CREATE TABLE "__mistri_inbox_notice" (
  id INTEGER PRIMARY KEY,
  app TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(app AS BLOB)) <= 128),
  recipient TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(recipient AS BLOB)) <= 320),
  at TEXT NOT NULL,
  resource TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(resource AS BLOB)) <= 512),
  key_json TEXT COLLATE BINARY NOT NULL CHECK (json_valid(key_json) AND length(CAST(key_json AS BLOB)) <= 2048),
  title TEXT NOT NULL CHECK (length(CAST(title AS BLOB)) <= 1000),
  uses_json TEXT NOT NULL CHECK (json_valid(uses_json) AND length(CAST(uses_json AS BLOB)) <= 4096),
  actor TEXT COLLATE BINARY NOT NULL,
  actor_name TEXT NOT NULL,
  action TEXT NOT NULL,
  read_at TEXT
);
CREATE TABLE "__mistri_inbox_mail" (
  notice INTEGER PRIMARY KEY,
  state TEXT COLLATE BINARY NOT NULL,
  attempts INTEGER NOT NULL,
  due_at TEXT NOT NULL,
  last_error TEXT
);
CREATE TABLE "__mistri_inbox_optout" (
  holder TEXT COLLATE BINARY PRIMARY KEY,
  at TEXT NOT NULL
);
CREATE INDEX "__mistri_inbox_notice_recipient" ON "__mistri_inbox_notice" (app, recipient, id);
INSERT INTO "__mistri_inbox_meta" ("singleton", "version") VALUES (1, 1);
